// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";

import { siblingSuiteCount, siblingSuiteNotice } from "./script-suites.mjs";

/// The defect: a green run that quietly means "half".
///
/// `script-tests.mjs` runs `scripts/*.test.mjs`. A second suite covers the same
/// scripts under vitest, and a full green local run was acted on as though it
/// were the whole story — the claim-gate and completion-offer guidance fix
/// passed every local assertion and failed CI on the mirrored ones, twice, on
/// work that was correct.
test("a runner that covers part of the suite says which part it does not", () => {
  const notice = siblingSuiteNotice(15);

  assert.match(notice, /NOT running 15 sibling test files/);
  assert.match(
    notice,
    /npm --prefix editors\/vscode test/,
    "naming the gap is only useful with the command that closes it",
  );
});

test("no sibling suite means no notice, rather than a reassuring one", () => {
  // A runner that announces "0 suites not run" trains people to skip the line,
  // and the line only matters on the day the count is not zero.
  assert.equal(siblingSuiteNotice(0), null);
});

test("the count reads the directory that actually holds the mirror", () => {
  const read = (dir) => {
    assert.equal(dir, "/repo/editors/vscode/scripts");
    return ["claim-gate.test.mjs", "helpers.mjs", "canonical-push.test.mjs"];
  };

  assert.equal(siblingSuiteCount("/repo", read), 2, "only test files count");
});

test("a missing mirror is zero, not a crash", () => {
  const read = () => {
    throw Object.assign(new Error("ENOENT"), { code: "ENOENT" });
  };

  assert.equal(siblingSuiteCount("/repo", read), 0);
});

test("the real repository still has a mirror, so the notice is live", () => {
  // If this ever reaches zero the mirror has moved or gone, and the notice
  // above would silently stop appearing — the same rot it exists to report.
  const url = new URL("..", import.meta.url);
  assert.ok(
    siblingSuiteCount(decodeURIComponent(url.pathname.replace(/^\//, ""))) > 0,
    "the sibling suite should be discoverable from the repository root",
  );
});
